(function(){const cv=document.getElementById('net'),ctx=cv.getContext('2d'),box=cv.parentNode;let W=0,H=0,N=[],mx=-999,my=-999,run=false;
 function size(){const r=box.getBoundingClientRect();if(!r.width)return;W=cv.width=r.width;H=cv.height=r.height;N=Array.from({length:Math.min(70,Math.floor(W*H/16000))},()=>({x:Math.random()*W,y:Math.random()*H,vx:(Math.random()-.5)*.4,vy:(Math.random()-.5)*.4}))}
 function frame(){if(!run)return;if(SCR){requestAnimationFrame(frame);return}ctx.clearRect(0,0,W,H);
  for(const a of N){a.x+=a.vx;a.y+=a.vy;if(a.x<0||a.x>W)a.vx*=-1;if(a.y<0||a.y>H)a.vy*=-1;const dx=a.x-mx,dy=a.y-my,d=Math.hypot(dx,dy);if(d<110&&d>0){a.x+=dx/d*.8;a.y+=dy/d*.8}}
  for(let i=0;i<N.length;i++){for(let j=i+1;j<N.length;j++){const d=Math.hypot(N[i].x-N[j].x,N[i].y-N[j].y);if(d<120){ctx.strokeStyle='rgba(255,255,255,'+(1-d/120)*.35+')';ctx.beginPath();ctx.moveTo(N[i].x,N[i].y);ctx.lineTo(N[j].x,N[j].y);ctx.stroke()}}
   ctx.fillStyle='rgba(245,184,0,.8)';ctx.beginPath();ctx.arc(N[i].x,N[i].y,1.8,0,6.3);ctx.fill()}
  requestAnimationFrame(frame)}
 new IntersectionObserver(es=>{const v=es[0].isIntersecting&&!RM;if(v&&!run){size();run=true;frame()}else if(!v)run=false;if(v)size()},{threshold:0}).observe(box);
 addEventListener('resize',size);box.addEventListener('mousemove',e=>{const r=box.getBoundingClientRect();mx=e.clientX-r.left;my=e.clientY-r.top});box.addEventListener('mouseleave',()=>{mx=my=-999})})();
